{
  "name": "@csuwl/opencode-memory-plugin",
  "version": "1.3.6",
  "description": "OpenClaw-style memory system for OpenCode with full automation and real vector search",
  "license": "MIT",
  "type": "module",
  "main": "plugin.js",
  "exports": {
    ".": {
      "import": "./plugin.js"
    }
  },
  "bin": {
    "opencode-memory-plugin": "bin/install.cjs",
    "opencode-memory": "bin/cli.cjs"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/csuwl/opencode-memory-plugin.git"
  },
  "keywords": [
    "opencode",
    "memory",
    "plugin",
    "ai",
    "openclaw",
    "vector-search",
    "semantic-search"
  ],
  "dependencies": {
    "@opencode-ai/plugin": "^1.2.15",
    "@huggingface/transformers": "^3.8.1",
    "better-sqlite3": "^11.7.0",
    "sqlite-vec": "^0.1.1"
  },
  "devDependencies": {
    "@types/node": "^22.10.5",
    "typescript": "^5.7.3"
  },
  "files": [
    "memory/",
    "lib/",
    "agents/",
    "scripts/",
    "bin/",
    "plugin.js",
    "index.js",
    "README.npm.md"
  ],
  "scripts": {
    "install": "node bin/install.cjs"
  }
}
